"""Writes tools/PROFE_INVENTORY.md, the feature-and-action inventory for Profe, from the same source the app uses (profe_registry.py),
so it can't drift from the code. Run after changing the registry: python3 tools/profe_inventory.py"""
import json, subprocess, sys, os, collections, datetime
T = os.path.dirname(os.path.abspath(__file__))
R = json.loads(subprocess.run([sys.executable, os.path.join(T, "profe_registry.py")], capture_output=True, text=True, check=True).stdout)
tests = {f[:-3] for f in os.listdir(os.path.join(T, "profe-tests")) if f.endswith(".js")}
A = {a["id"]: a for a in R["actions"]}
out = ["# Profe feature-and-action inventory", "", "Generated by `tools/profe_inventory.py` from `tools/profe_registry.py` on " + datetime.date.today().isoformat() + ". Do not edit by hand.", "",
       "**Sources of truth:** voice actions and their patterns live in `tools/profe_registry.py` (built into `index.html` as `pv-registry`); handlers in `tools/pvoice.js` (`PVH`); every route in `route()` and every `data-act` button must have a status here, which `node tools/profe_check.js` enforces in CI.", "",
       "**Status words:** *complete* = a voice command runs it and checks the outcome; *pending* = reachable by touch, voice planned (reason given); *unsuitable* = not a sensible voice action (reason given). Any button with a visible label can also be pressed by naming it (\"tap Music\") through `find.open`, which checks that something changed before reporting success.", ""]
by = collections.OrderedDict()
for a in R["actions"]: by.setdefault(a["feature"], []).append(a)
out += ["## Voice actions (%d)" % len(R["actions"]), "", "| Feature | Action | What it does | Entry point | Inputs | Confirms first | Success check | Test |", "| --- | --- | --- | --- | --- | --- | --- | --- |"]
for f, xs in by.items():
    for a in xs:
        ep = ("route `" + a["route"] + "`" if a.get("route") else "") + (" · button `" + a["act"] + "`" if a.get("act") else "") + (" · when " + a["when"] if a.get("when") else "")
        t = a.get("test") or ""; t = t + ("" if t in tests else " (missing)")
        out.append("| %s | `%s` | %s | %s | %s | %s | %s | %s |" % (f, a["id"], a["purpose"].replace("|", "/"), ep.strip(" ·") or "anywhere", ", ".join(a.get("params") or []) or "—", "yes" if a.get("confirm") else "no", (a.get("verify") or "").replace("|", "/"), t))
def table(title, d):
    rows = []
    for k, v in sorted(d.items()):
        if isinstance(v, str): rows.append(("complete", k, "`" + v + "`"))
        else: rows.append((v.get("voice"), k, v.get("why", "").replace("|", "/")))
    c = collections.Counter(r[0] for r in rows)
    out.extend(["", "## " + title + " (%d: %s)" % (len(rows), ", ".join("%d %s" % (n, s) for s, n in c.most_common())), "", "| Status | Key | Voice action or reason |", "| --- | --- | --- |"])
    for s in ("complete", "pending", "unsuitable"):
        out.extend("| %s | `%s` | %s |" % r for r in rows if r[0] == s)
table("Screens and routes", R["routes"])
table("On-screen buttons (data-act)", R["acts"])
out += ["", "## Content Profe can find by name (`find.open`, built at runtime by `pvIndex()` in tools/pvoice.js)", "",
        "Screens · levels · every unit (Spanish and English titles) · level flashcards and exams · every listening and reading text (songs, podcasts, stories, poems, news, history, culture, readings) and your own saved texts · every video with its singers/channel · grammar guides · grammar pages · writing tasks · the buttons, filters and links visible on the current screen. Spanish titles also answer to their English words through the app's dictionary (\"the market\" → «En el mercado»). Clear matches run at once; otherwise Profe offers the closest three and you answer with the number.", "",
        "## Not reachable by voice (known gaps)", "", "- Individual dictionary word pages and individual verbs by name (Profe answers meaning and conjugation questions instead).",
        "- Answering inside exam papers and the quick drill by voice (answers by touch; the speaking paper uses the microphone).", "- Anything that needs typing long text (essays) — dictation into the writing box is not wired to Profe.", ""]
open(os.path.join(T, "PROFE_INVENTORY.md"), "w", encoding="utf-8").write("\n".join(out) + "\n")
print("wrote tools/PROFE_INVENTORY.md:", len(R["actions"]), "actions,", len(R["routes"]), "routes,", len(R["acts"]), "buttons")
